<?php require_once __DIR__.'/../includes/auth.php';if(admin_logged_in()){header('Location:index.php');exit;}$e='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=db()->prepare('SELECT * FROM admins WHERE username=? AND active=1');$s->execute([trim($_POST['username']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){$_SESSION['admin_id']=$a['id'];$_SESSION['admin_username']=$a['username'];header('Location:index.php');exit;}$e='Invalid admin username or password.';}$title='Admin Login - '.APP_NAME;$isAdminLogin=true;$isAdmin=true;include '../includes/header.php';?><h1>Welcome back</h1><p>Sign in to manage your SokoPulse store.</p><?php if($e):?><div class="auth-error"><?=htmlspecialchars($e)?></div><?php endif;?><form method="post"><div class="admin-field"><label>Username</label><input name="username" required autocomplete="username"></div><div class="admin-field"><label>Password</label><input type="password" name="password" required autocomplete="current-password"></div><button class="admin-btn" type="submit">Sign in to Dashboard</button></form><?php include '../includes/footer.php';?>
